/** Filled star, for review sections. */
function star(string $class = 'h-5 w-5'): string
{
    return '<svg class="' . e($class) . '" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">'
        . '<path fill-rule="evenodd" d="M10.788 3.21c.448-1.077 1.976-1.077 2.424 0l2.082 5.006 5.404.433c1.164.093 1.636 1.545.749 2.305l-4.117 3.527 1.257 5.273c.271 1.136-.964 2.033-1.96 1.425L12 18.354 7.373 21.18c-.996.608-2.231-.29-1.96-1.425l1.257-5.273-4.117-3.527c-.887-.76-.415-2.212.749-2.305l5.404-.433 2.082-5.005z" clip-rule="evenodd" /></svg>';
}

/**
 * Small round headshot. Falls back to a lettered disc when the file is
 * missing, so a testimonial never shows a broken avatar.
 */
function avatar(string $file, string $name, string $class = 'h-14 w-14'): string
{
    if (is_file(__DIR__ . '/../assets/img/' . $file)) {
        return '<img src="assets/img/' . e($file) . '" alt="' . e($name) . '" loading="lazy" decoding="async"'
            . ' class="' . e($class) . ' shrink-0 rounded-full object-cover">';
    }

    return '<span aria-hidden="true" class="' . e($class)
        . ' grid shrink-0 place-items-center rounded-full bg-brand-ocean font-display text-lg font-bold text-white">'
        . e(mb_substr($name, 0, 1)) . '</span>';
}

/**
 * Renders a photo if it exists in assets/img/, otherwise a designed
 * placeholder so the layout never breaks. Drop real photos in with the
 * same filename and they appear automatically.
 */
function photo(string $file, string $alt, string $imgClass = '', string $label = 'Photo'): string
{
    $path = __DIR__ . '/../assets/img/' . $file;

    if (is_file($path)) {
        return '<img src="assets/img/' . e($file) . '" alt="' . e($alt) . '" class="' . e($imgClass) . '" loading="lazy" decoding="async">';
    }

    return '<div class="' . e($imgClass) . ' flex flex-col items-center justify-center gap-3 bg-gradient-to-br from-brand-mint via-brand-sand to-brand-gold/30 text-brand-teal"'
        . ' role="img" aria-label="' . e($alt) . '">'
        . icon('users', 'h-12 w-12 opacity-50')
        . '<p class="px-6 text-center font-sans text-sm font-semibold uppercase tracking-wider opacity-70">' . e($label) . '</p>'
        . '<p class="px-6 text-center font-sans text-xs opacity-60">assets/img/' . e($file) . '</p>'
        . '</div>';
}
